CLAIMS=[
(1001,"technique-relevance","数据操纵要求业务数据仍可被消费但值、消息或运行结果错误并影响流程/决策，区别于销毁、加密不可读和直接展示篡改。","Data Manipulation requires business data to remain consumable while values, messages, or runtime results are wrong and affect process or decision, distinct from destruction, unreadable encryption, and direct display defacement.",["NJT-0203"],["REF-000883","REF-000997","REF-000998"],"directly-observed","high"),
(1002,"subtechnique-existence","FIN13 创建符合现有 schema、关系和业务节奏的欺诈交易并渐进抽取价值，证明错误值可保留业务合形外观。","FIN13 created fraudulent transactions conforming to existing schemas, relationships, and business cadence while siphoning value incrementally, establishing that false values can preserve a business-conforming appearance.",["NJT-0203","NJS-0203-001","NM-FD"],["REF-000997"],"directly-observed","high"),
(1003,"subtechnique-existence","APT38/DYEPACK 同时操纵数据库行、打印消息和 PDF 表示，制造同一业务对象跨表示不一致以隐藏 SWIFT 欺诈。","APT38 or DYEPACK manipulated database rows, printer messages, and PDF representations, creating cross-representation inconsistency for the same business object to hide SWIFT fraud.",["NJT-0203","NJS-0203-002","NM-BT"],["REF-000998"],"directly-observed","high"),
(1004,"detection","业务合形值操纵检测需要 CDC before/after、writer/transaction、业务不变量、历史关系和下游 outcome；schema 有效不能证明正确。","Detection of business-conforming value manipulation needs CDC before and after, writer and transaction, business invariants, historical relationships, and downstream outcome; valid schema alone does not prove correctness.",["NJT-0203","NJS-0203-001","DET-000235"],["REF-000999","REF-001000","REF-001001"],"strongly-inferred","high"),
(1005,"detection","跨表示完整性检测需为同一业务对象连接 DB、消息、PDF/打印/UI 和外部回执的稳定 ID、版本和 digest；单面检查会遗漏分歧。","Cross-representation integrity detection needs stable IDs, versions, and digests joining DB, messages, PDF or print or UI, and external receipts for one business object; one-surface checking misses divergence.",["NJT-0203","NJS-0203-002","DET-000235"],["REF-000998","REF-000999","REF-001001","REF-001002"],"strongly-inferred","high"),
(1006,"mitigation","业务不变量、端到端 provenance、签名/版本与独立对账能限制隐蔽数据操纵，但被控制的权威源或同步篡改多表示仍有残余风险。","Business invariants, end-to-end provenance, signatures or versions, and independent reconciliation constrain covert manipulation, while a compromised authoritative source or synchronized changes across representations leave residual risk.",["NJT-0203","NJS-0203-001","NJS-0203-002"],["REF-001001","REF-001002"],"strongly-inferred","high"),
(1007,"technique-relevance","金融盗窃只有在受害方已扣账/失去价值控制且攻击者受益方已成功入账/取得控制时完成；金融动机、凭据、指令或 pending 交易不够。","Financial Theft completes only when the victim is debited or loses value control and the attacker beneficiary is successfully credited or gains control; financial motive, credentials, instructions, or a pending transaction are insufficient.",["NJT-0204"],["REF-001003","REF-001004","REF-001009","REF-001010"],"directly-observed","high"),
(1008,"subtechnique-existence","攻击者只替换熟悉业务指令中的受益账户，使金额、供应商、发件人与流程保持正常，而结算价值进入攻击者账户。","An attacker substitutes only the beneficiary account in a familiar business instruction so amount, vendor, sender, and workflow remain normal while settled value enters an attacker account.",["NJT-0204","NJS-0204-001","NM-FD"],["REF-001004","REF-001005","REF-001006"],"directly-observed","high"),
(1009,"subtechnique-existence","窃取价值可在入账后迅速拆分至多账户、银行、国家或链上地址，使冻结窗口和单账户观察不足。","Stolen value can be rapidly split after credit across multiple accounts, banks, countries, or on-chain addresses, making freeze windows and single-account observation insufficient.",["NJT-0204","NJS-0204-002","NM-ST"],["REF-001007","REF-001008"],"directly-observed","high"),
(1010,"detection","受益账户替换检测需连接业务指令版本、独立受益人确认、ISO 20022 transaction IDs、PDNG/ACSC/RJCT 与 debit/credit outcome。","Beneficiary-substitution detection needs instruction versions, independent beneficiary confirmation, ISO 20022 transaction IDs, PDNG or ACSC or RJCT, and debit and credit outcomes.",["NJT-0204","NJS-0204-001","DET-000236"],["REF-001009","REF-001010","REF-001011","REF-001012"],"strongly-inferred","high"),
(1011,"detection","多跳价值分散检测需以 conserved amount/currency、时间、来源 transaction 和 successor accounts 建图；公开案例不足以提供通用 hop/金额阈值。","Multi-hop value-dispersion detection needs graphs of conserved amount and currency, time, source transaction, and successor accounts; public cases do not provide universal hop or amount thresholds.",["NJT-0204","NJS-0204-002","DET-000236"],["REF-001007","REF-001008","REF-001013"],"strongly-inferred","high"),
(1012,"mitigation","独立受益人确认、transaction-master 完整性、结算 hold/双人批准和 24 小时内机构/执法恢复流程可降低已完成盗窃与分散损失。","Independent beneficiary confirmation, transaction-master integrity, settlement holds or dual approval, and institution or law-enforcement recovery within 24 hours reduce completed theft and dispersion loss.",["NJT-0204","NJS-0204-001","NJS-0204-002"],["REF-001004","REF-001006","REF-001009","REF-001012","REF-001013"],"strongly-inferred","high"),
(1013,"technique-relevance","邮件轰炸只有在大量邮件造成合法邮件埋没、处理/投递困难、接收限额或业务中断时完成；高量本身不够。","Email Bombing completes only when message volume causes legitimate-message burial, handling or delivery difficulty, receive-limit impact, or business interruption; volume alone is insufficient.",["NJT-0205"],["REF-001015","REF-001016","REF-001021"],"directly-observed","high"),
(1014,"subtechnique-existence","攻击者可把一个收件人订阅到大量合法第三方列表，使邮件通过认证且来自众多真实发送者，削弱 sender/blocklist 聚类。","An attacker can subscribe one recipient to many legitimate third-party lists so mail authenticates and comes from many real senders, weakening sender or blocklist clustering.",["NJT-0205","NJS-0205-001","NM-FD"],["REF-001016","REF-001017","REF-001018","REF-001019"],"directly-observed","high"),
(1015,"subtechnique-existence","邮件洪泛可与重置、金融或安全通知时间同步，使关键后果消息在噪声中埋没，而整体邮件量不说明哪一封重要。","Mail flooding can synchronize with password-reset, financial, or security notifications so consequential messages are buried in noise while aggregate volume does not identify which message matters.",["NJT-0205","NJS-0205-002","NM-ST"],["REF-001016","REF-001020","REF-000567"],"strongly-inferred","medium"),
(1016,"detection","合法发送者 fan-out 检测需按 recipient 聚合 authenticated sender/domain/IP、EmailClusterId、campaign/list 特征、delivery 与 mailbox 结果，而非只按垃圾分类。","Legitimate-sender fan-out detection needs recipient aggregation of authenticated sender, domain, IP, EmailClusterId, campaign or list features, delivery, and mailbox outcomes rather than spam classification alone.",["NJT-0205","NJS-0205-001","DET-000237"],["REF-000609","REF-001016","REF-001020","REF-001022"],"strongly-inferred","high"),
(1017,"detection","关键消息埋没检测需连接 consequential notification、同 recipient 洪泛窗口、folder/read/access 和业务 action/SLA；无 MailItemsAccessed 不证明未读。","Consequential-message burial detection needs to join consequential notifications, the same-recipient flood window, folder, read or access, and business action or SLA; absent MailItemsAccessed does not prove unread.",["NJT-0205","NJS-0205-002","DET-000237"],["REF-001020","REF-000567","REF-001022"],"strongly-inferred","high"),
(1018,"mitigation","confirmed opt-in/CAPTCHA、recipient-centric fan-in controls、campaign cleanup、priority channels and receive-limit resilience can preserve mail continuity but may affect legitimate newsletters and high-volume workflows.","Confirmed opt-in or CAPTCHA, recipient-centric fan-in controls, campaign cleanup, priority channels, and receive-limit resilience preserve mail continuity but can affect legitimate newsletters and high-volume workflows.",["NJT-0205","NJS-0205-001","NJS-0205-002"],["REF-001016","REF-001021","REF-001023"],"strongly-inferred","high"),
]
